def solve(N):
    if N == 1:
        return 3
    M = N - 1
    idx = M - 1
    k = idx // 3 + 1
    r = idx % 3
    if r == 0:
        return 4 * k + 1
    elif r == 1:
        return 4 * k + 3
    else:
        return 4 * k + 4

def main():
    import sys
    N = int(sys.stdin.readline())
    print(solve(N))

if __name__ == "__main__":
    main()
