import sys
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    f = [0] * (n + 1)
    for i in range(1, n + 1):
        f[i] = int(data[idx]); idx += 1

    adj = [[] for _ in range(n + 1)]
    radj = [[] for _ in range(n + 1)]

    for _ in range(m):
        a = int(data[idx]); idx += 1
        b = int(data[idx]); idx += 1
        adj[a].append(b)
        radj[b].append(a)

    # Forward reachability: from assign nodes (f==1), do not expand past
    # another assign node (except the starting one).
    reach = [False] * (n + 1)
    dq = deque()
    for i in range(1, n + 1):
        if f[i] == 1:
            reach[i] = True
            dq.append(i)

    while dq:
        u = dq.popleft()
        for v in adj[u]:
            if not reach[v]:
                reach[v] = True
                if f[v] != 1:
                    dq.append(v)

    # Backward reachability: from use nodes (f==2), do not expand past
    # a node that is an assign node (f==1) when going backward, except
    # marking it reachable.
    can_use = [False] * (n + 1)
    dq = deque()
    for i in range(1, n + 1):
        if f[i] == 2:
            can_use[i] = True
            dq.append(i)

    while dq:
        u = dq.popleft()
        for p in radj[u]:
            if not can_use[p]:
                can_use[p] = True
                if f[p] != 1:
                    dq.append(p)

    res = []
    for i in range(1, n + 1):
        res.append('1' if reach[i] and can_use[i] else '0')

    sys.stdout.write('\n'.join(res) + '\n')

if __name__ == '__main__':
    main()
