def psi(n, d):
    s = str(n).zfill(d)
    r = ''.join(str(9 - int(c)) for c in s)
    return int(r)

def main():
    l, r = map(int, input().split())
    best = 0
    dl = len(str(l))
    dr = len(str(r))
    for d in range(dl, dr + 1):
        if d == 1:
            low_d = 1
        else:
            low_d = 10 ** (d - 1)
        high_d = 10 ** d - 1
        low = max(l, low_d)
        high = min(r, high_d)
        if low > high:
            continue
        S = 10 ** d - 1
        mid = S // 2
        candidates = {low, high, min(max(mid, low), high), min(max(mid + 1, low), high)}
        for c in candidates:
            w = c * psi(c, d)
            if w > best:
                best = w
    print(best)

main()
