import sys

def gen_powers(base, limit):
    res = [1]
    val = base
    while val <= limit:
        res.append(val)
        if val > limit // base + 1:
            break
        val *= base
    return res

def main():
    data = sys.stdin.read().split()
    x, y, l, r = map(int, data[:4])

    xs = gen_powers(x, r)
    ys = gen_powers(y, r)

    unlucky = set()
    for a in xs:
        for b in ys:
            s = a + b
            if l <= s <= r:
                unlucky.add(s)

    if not unlucky:
        print(r - l + 1)
        return

    lst = sorted(unlucky)
    prev = l - 1
    ans = 0
    for u in lst:
        gap = u - prev - 1
        if gap > ans:
            ans = gap
        prev = u
    gap = r - prev
    if gap > ans:
        ans = gap

    print(ans)

if __name__ == "__main__":
    main()
